/* ch116 - Pointer move, button, and wheel events without hardware dependency. */
#include "tut_capture.h"

static xge_font_t g_font;
static int g_font_loaded,g_ran,g_verified,g_events,g_down;
static float g_x,g_y,g_wheel;
static const char* find_font(void){static const char* p[]={"C:\\Windows\\Fonts\\segoeui.ttf","C:\\Windows\\Fonts\\arial.ttf"};int i;for(i=0;i<2;i++){FILE*f=fopen(p[i],"rb");if(f){fclose(f);return p[i];}}return NULL;}
static void label(const char*s,float x,float y,uint32_t c){if(g_font_loaded)xgeTextDraw(&g_font,s,x,y,c);}
static void post_pointer(int type,float x,float y,float dx,float dy,int button){xge_input_event_t e;memset(&e,0,sizeof(e));e.iSize=sizeof(e);e.iType=type;e.fX=x;e.fY=y;e.fDX=dx;e.fDY=dy;e.iButton=button;(void)xgeInputEventPost(&e);}
static void replay_and_consume(void){xge_input_event_t e;post_pointer(XGE_EVENT_MOUSE_MOVE,270,300,270,300,0);post_pointer(XGE_EVENT_MOUSE_DOWN,270,300,0,0,XGE_MOUSE_LEFT);post_pointer(XGE_EVENT_MOUSE_WHEEL,270,300,0,1,0);post_pointer(XGE_EVENT_MOUSE_UP,420,245,150,-55,XGE_MOUSE_LEFT);while(xgeInputEventGet(&e)>0){g_events++;if(e.iType==XGE_EVENT_MOUSE_MOVE||e.iType==XGE_EVENT_MOUSE_DOWN||e.iType==XGE_EVENT_MOUSE_UP){g_x=e.fX;g_y=e.fY;}if(e.iType==XGE_EVENT_MOUSE_DOWN)g_down=1;if(e.iType==XGE_EVENT_MOUSE_UP)g_down=0;if(e.iType==XGE_EVENT_MOUSE_WHEEL)g_wheel+=e.fDY;}g_verified=(g_events==4&&!g_down&&g_x==420&&g_y==245&&g_wheel==1);printf("ch116 pointer self-test: %s\n",g_verified?"PASS":"FAIL");}
static void draw_scene(void){uint32_t status;if(!g_ran){const char*p=find_font();if(p&&xgeFontLoad(&g_font,p,22)==XGE_OK)g_font_loaded=1;replay_and_consume();g_ran=1;}status=g_verified?XGE_COLOR_RGBA(79,216,194,255):XGE_COLOR_RGBA(255,107,94,255);xgeShapeRectFill((xge_rect_t){70,58,660,80},XGE_COLOR_RGBA(23,34,45,255));xgeShapeRectStroke((xge_rect_t){70,58,660,80},2,status);xgeShapeCircleFill(108,98,16,status);label("XGE pointer event stream",142,78,XGE_COLOR_RGBA(231,238,246,255));label(g_verified?"move + down + wheel + up replay: PASS":"pointer self-test: FAIL",142,106,status);xgeShapeLine(270,300,g_x,g_y,4,XGE_COLOR_RGBA(109,179,242,255));xgeShapeCircleFill(270,300,15,XGE_COLOR_RGBA(79,216,194,255));xgeShapeCircleFill(g_x,g_y,20,XGE_COLOR_RGBA(255,180,84,255));xgeShapeRectStroke((xge_rect_t){145,450,510,60},2,XGE_COLOR_RGBA(79,216,194,255));label("final pointer: (420, 245)    wheel delta: +1",170,470,XGE_COLOR_RGBA(219,228,240,255));label("Use fX/fY for positions and fDX/fDY for deltas; button state belongs to the control.",85,550,XGE_COLOR_RGBA(148,163,184,255));}
int main(int argc,char**argv){int r=tut_run(draw_scene,"ch116-pointer",argc,argv);return(r==0&&(!g_ran||g_verified))?0:1;}
